use vstd::prelude::*;

verus! {

fn flip(a: &mut Vec<i32>, num: usize)
    requires
        a@.len() > 0,
        num < a@.len(),
    ensures
        a@.len() == old(a)@.len(),
        // Elements outside the flipped prefix [0..=num] are unchanged
        forall|k: int| num < k && k < a@.len() ==> a@[k] == old(a)@[k],
        // The prefix [0..=num] is reversed
        forall|k: int|
            0 <= k && k <= num as int
            ==> a@[k] == old(a)@[num as int - k],
{
    // Assumptions from the problem:
    // - a is non-empty
    // - num < a.len()
    debug_assert!(!a.is_empty());
    debug_assert!(num < a.len());

    let mut i: usize = 0;
    let mut j: usize = num;

    while i < j
        invariant
            a@.len() == old(a)@.len(),
            num < a@.len(),
            i <= j,
            j <= num,
            // Outside [0..=num] nothing changes
            forall|k: int| num < k && k < a@.len() ==> a@[k] == old(a)@[k],
            // Left part already matches the reversed target
            forall|k: int|
                0 <= k && k < i as int
                ==> a@[k] == old(a)@[num as int - k],
            // Right part already matches the reversed target
            forall|k: int|
                j as int < k && k <= num as int
                ==> a@[k] == old(a)@[num as int - k],
        decreases (j - i),
    {
        a.swap(i, j);
        i += 1;
        j -= 1;
    }
}

} // verus!

